      "ref": "import pandas as pd\nlong = pd.DataFrame({'id': [1, 1, 2, 2], 'quarter': ['Q1', 'Q2', 'Q1', 'Q2'], 'rev': [100, 150, 200, 250]})\nwide = long.pivot(index='id', columns='quarter', values='rev').reset_index()\nwide.columns.name = None\nq3_cols = wide.columns.tolist()\nq3_q1_vals = wide['Q1'].tolist()\nprint(f'{q3_cols=}, {q3_q1_vals=}')\n",
